//! 🧪️ Actual donated recursive Value controls preserve leaf pages and exact typed children.
use super::*;
use semio_framework_plugin::{AppRenderOperationContext,ChildContentView};
use semio_framework_ui_contract::{Component,OriginalBuiltTreeRetirement};
use semio_s_artifact_stdio_ifc_4_model::standards::v4::subsets::any::schema::snapshot::{IfcEntity,IfcTypedValue};
fn value(row:&serde_json::Value)->IfcValue{match row["kind"].as_str().unwrap(){"unset"=>IfcValue::Unset,"derived"=>IfcValue::Derived,"enum"=>IfcValue::Enum(row["value"].as_str().unwrap().into()),"binary"=>IfcValue::Binary(row["value"].as_str().unwrap().into()),"string"=>IfcValue::String(row["value"].as_str().unwrap().into()),"integer"=>IfcValue::Integer(row["value"].as_str().unwrap().parse().unwrap()),"reference"=>IfcValue::Reference(row["value"].as_str().unwrap().parse().unwrap()),"real"=>IfcValue::Real(f64::from_bits(row["value"]["bits"].as_str().unwrap().parse().unwrap())),"aggregate"=>IfcValue::Aggregate(row["value"].as_array().unwrap().iter().map(value).collect()),"typedValue"=>IfcValue::TypedValue(IfcTypedValue{name:row["value"]["name"].as_str().unwrap().into(),items:row["value"]["items"].as_array().unwrap().iter().map(value).collect()}),_=>panic!("closed original vector")}}
#[test]
fn original_recursive_controller_pages_and_child_controls_are_real_bound_editors(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../🔎️details/🧪️tests/type-value-select-input.json")).unwrap();
 for row in law["cases"].as_array().unwrap(){
  let snapshot=std::sync::Arc::new(IfcSnapshot{entities:law["source"]["entities"].as_array().unwrap().iter().map(|entity|IfcEntity{id:entity["id"].as_str().unwrap().parse().unwrap(),name:entity["name"].as_str().unwrap().into(),args:entity["args"].as_array().unwrap().iter().map(value).collect(),complex:Vec::new()}).collect(),..Default::default()});
  let history=semio_framework_plugin::HistoryView::empty();let view=staged_view();let operation=AppRenderOperationContext{app_instance_id:17,base_revision:semio_framework_job::RevisionId(0),generation:semio_framework_job::Generation(1),canonical_base_revision:[0;32],mounted_policy:semio_framework_plugin::app_testing::artifact_app_laws::fixture_mounted_policy()};let doc=semio_framework_async::poll::resolve_ready(ArtifactView::with_render_context(snapshot.as_ref(),&history,ChildContentView::EMPTY,operation,"actual-recursive-value",None));let mut caller=OriginalWorkFixture::new();let mut work=caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::begin_render_work(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,cx)).unwrap().unwrap();
  let rows=if row["member"].is_null(){serde_json::json!([])}else{serde_json::json!([{"index":"0","value":{"kind":"typedValue","value":{"name":row["member"],"items":row["items"]}}}])};let mut request=staged_request(&serde_json::json!({"path":"/entities/0","value":{"$ifcType":law["entity"],"$ifcInputs":rows}}));request.token.action=editing::SET_SNAPSHOT_VALUE_ACTION_ID.into();let mut donor=Some(request);
  for _ in 0..16{if caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::receive_render_work_request(&mut work,&mut donor,&view,cx)).unwrap().is_some(){break;}}assert!(donor.is_none());let mut output=None;
  for turn in 0..1000000{match caller.work_turn(staged_grant(),1000,|cx|Ok(work.render(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,&snapshot,&doc,&view,cx))).unwrap(){Ok(Some(tree))=>{output=Some(tree);break;},Ok(None)=>{},Err(_)=>panic!("original draft stays editable: {}",row["id"])}assert!(turn<999999);}
  let tree=output.unwrap();let Component::Extension(status)=&tree.root.children.get(0).unwrap().component else{panic!("original readiness")};assert_eq!(serde_json::to_value(&status.props).unwrap()["ready"],row["domain"]);let fields=tree.root.children.iter().skip(1).collect::<Vec<_>>();let node=fields[0].children.get(0).unwrap();let Component::Select(select)=&node.component else{panic!("actual paged leaf discriminator")};assert!(select.items.len()>=31&&select.items.len()<=32);assert!(!node.bindings.is_empty());
  if let Some(items)=row["items"].as_array(){let node=fields[1].children.get(0).unwrap();assert!(!node.bindings.is_empty());match row["member"].as_str().unwrap(){"IFCBOOLEAN"|"IFCLOGICAL"=>assert!(matches!(&node.component,Component::Select(_))),"IFCCOMPLEXNUMBER"|"IFCCOMPOUNDPLANEANGLEMEASURE"=>{assert!(matches!(&node.component,Component::Button(_)));if let Some(members)=items.first().and_then(|child|child["value"].as_array()){for(index,member)in members.iter().take(7).enumerate(){let Component::Input(input)=&fields[2+2*index].children.get(0).unwrap().component else{panic!("exact collection member")};let raw=if member["kind"]=="real"{member["value"]["bits"].as_str().unwrap()}else{member["value"].as_str().unwrap()};assert_eq!(input.value.as_ref(),raw);}}},"IFCNUMERICMEASURE"=>assert!(matches!(&node.component,Component::Select(_))),_=>assert!(matches!(&node.component,Component::Input(_)))}}
  let mut close=OriginalBuiltTreeRetirement::new(tree.root);for _ in 0..1000000{if close.terminal_is_empty(){break;}caller.turn(staged_grant(),|cx|cx.with_original_retirement(|cx|{let demand=close.next_demand(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|close.step(grant))?;Ok(())})).unwrap();}assert!(close.terminal_is_empty());caller.cancel().cancel_now();retire_staged(&mut caller,&mut Some(work));assert_eq!(std::sync::Arc::strong_count(&snapshot),1);caller.finish();
 }
}
